SELECT 
FROM ai_business_process_node_run
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
ORDER BY create_time ASC, id ASC

SELECT 
FROM ai_business_process_node_run
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND node_id = #{nodeId}
ORDER BY attempt_no DESC, id DESC
LIMIT 1

SELECT 
FROM ai_business_process_node_run
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND node_id = #{nodeId}
  AND correlation_id = #{correlationId}
  AND status = 'WAITING'
LIMIT 1

SELECT 
FROM ai_business_process_node_run
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND status = 'FAILED'
  AND next_retry_time IS NOT NULL
  AND next_retry_time <= #{before}
ORDER BY next_retry_time ASC, id ASC
LIMIT #{limit}

SELECT COALESCE(MAX(attempt_no), 0)
FROM ai_business_process_node_run
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND node_id = #{nodeId}

mapper.update:
UPDATE ai_business_process_node_run SET status = #{nextStatus}, correlation_id = #{correlationId}, output_summary = #{outputSummary}, error_code = #{errorCode}, error_summary = #{errorSummary}, next_retry_time = #{nextRetryTime}, end_time = CASE WHEN #{nextStatus} IN ('SUCCESS', 'FAILED', 'CANCELED') THEN NOW() ELSE NULL END, update_time = NOW() WHERE tenant_id = #{tenantId} AND id = #{id} AND status = #{expectedStatus}
AND correlation_id = #{expectedCorrelationId}
AND correlation_id IS NULL
